class TreeNode:
    """Node for the binary search tree."""
    def __init__(self, key):
        self.key = key          # value stored in the node
        self.left = None        # left child
        self.right = None       # right child


class BinarySearchTree:
    """Binary Search Tree with insert, find and in-order traversal."""
    def __init__(self):
        self.root = None        # root of the tree

    def insert(self, key):
        """Insert a key into the BST."""
        new_node = TreeNode(key)
        if self.root is None:
            # empty tree, new node becomes root
            self.root = new_node
            return

        current = self.root
        while True:
            if key < current.key:
                # go left
                if current.left is None:
                    current.left = new_node
                    break
                current = current.left
            elif key > current.key:
                # go right
                if current.right is None:
                    current.right = new_node
                    break
                current = current.right
            else:
                # duplicate key, do nothing
                break

    def find(self, key):
        """Return True if key exists in the BST, else False."""
        current = self.root
        while current is not None:
            if key == current.key:
                return True
            elif key < current.key:
                current = current.left
            else:
                current = current.right
        return False

    def _inorder(self, node, result):
        """Helper recursive in-order traversal."""
        if node is None:
            return
        # visit left subtree
        self._inorder(node.left, result)
        # visit node
        result.append(node.key)
        # visit right subtree
        self._inorder(node.right, result)

    def inorder_traversal(self):
        """Return list of keys in in-order sorted order."""
        result = []
        self._inorder(self.root, result)
        return result
